-- River Survival: Escape & Pursuit: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'river_survival', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["surv-01",1,"Thoát khỏi Trại Cờ Cam","File \"Thay game mới\" mục II.3 (cảnh mở đầu cọc gỗ, Task Panel, 2 đội) + video bờ sông đá sỏi, rừng thông, nhà gỗ cũ trong cỏ cao.","Trò chơi trận giả cuối khóa của Trại Hè Sông Ngọc bắt đầu bằng một bất ngờ: Đội Săn Tìm phục kích từ trưa, dồn cả nhóm bạn vào Chuồng Gỗ và quấn dây thừng chặt quanh cổng. Minh Khôi phát hiện một tảng đá sắc cạnh hàng rào, cả nhóm thay nhau mài dây và bung cổng thoát ra. Từ đây phải sống sót đến khi trống trại vang lúc hoàng hôn: tìm nước sạch, nhặt đá và gậy dựng bẫy phòng thủ, giải mật thư của bác Kiểm lâm Sáu để tìm hang trú an toàn, và xóa dấu chân trên cát. Đội Săn Tìm của Hạ Vy có bản đồ quét dấu vết và quyết bắt hơn một nửa số người. Nhưng giữa trận, trại cờ cam để quên một thùng Lưới Gắn Thẻ dự phòng; ai lẻn đến được sẽ lật ngược thế cờ, đuổi ngược Đội Săn Tìm và giải cứu đồng đội.","Bờ sông đá sỏi lúc chiều tà, rừng thông phía sau, một nhà gỗ cũ giữa bãi cỏ cao. Trại của Đội Săn Tìm cắm cờ cam ở đầu bãi. Trời chuyển từ vàng cam sang tím, sương bắt đầu lên mặt nước. Ở góc bờ có một chiếc thuyền chèo cũ phủ lưới bỏ quên.",[{"n":1,"title":"Chuồng Gỗ và sợi dây thừng","minutes":5,"optional":false,"goal":"Mở màn: thoát khỏi Chuồng Gỗ; Đội Săn Tìm nhận bản đồ và chia khu.","beats":["Phim ngắn 20 giây: cổng chuồng quấn dây, Minh Khôi nhìn thấy đá sắc.","Mỗi câu đúng là một nhát mài dây; thanh dây đứt dần, cổng bung khi cả nhóm đủ 5 câu.","Đội Săn Tìm đứng ở trại cờ cam, đếm ngược 60 giây rồi mới được xuất phát.","Tường gỗ có cửa sổ của Chuồng Gỗ: nhìn qua cửa sổ đọc câu hỏi để đoán chỗ giấu dây."],"question_hook":"Câu hỏi hiện ngay trên sợi dây thừng; đúng thì dây sờn thêm một đoạn, sai thì dây chỉ rung nhẹ.","reward":"Mở khóa đôi giày chạy và bản đồ nhỏ.","vocab":["rope","rock","escape","cut","run","wall","window"],"assets":["surv_holding_pen","surv_rope","surv_rope_cut","surv_sharp_rock","surv_stake","surv_rival_tent","surv_flag","anim_rope_rub","surv_pen_wall_window"],"subtitles":[{"en":"Cut the rope and run fast!","vi":"Cắt dây thừng rồi chạy thật nhanh!","parts":["Cắt ",["rope","dây thừng",1]," rồi ",["run","chạy",0]," thật nhanh!"]},{"en":"The Seekers get a map, so we must escape!","vi":"Đội Săn Tìm nhận bản đồ, mình phải trốn thoát!","parts":["Đội Săn Tìm nhận bản đồ, mình phải ",["escape","trốn thoát",3],"!"]}]},{"n":2,"title":"Nhiệm vụ 1: Nước sạch bên suối","minutes":5,"optional":false,"goal":"Tìm dòng suối trong, lọc nước vào bình trước khi Đội Săn Tìm khép vòng.","beats":["Ba con suối: một đục bùn, một có lá mục, một trong vắt sau khe đá.","Đội Săn Tìm mở kỹ năng Quét dấu chân lần đầu.","Người Chạy Trốn bị bắt được đưa về Chuồng Gỗ, bắt đầu giải mật thư hỗ trợ.","Suối trong chảy ra từ bãi đá: gọi đúng tên mới được múc nước."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Chọn đúng con suối cũng là một câu trắc nghiệm.","reward":"1-3 sao; nhận Bình nước (hồi sức chạy).","vocab":["water","stream","clean","dirty","bottle","spring","clear water"],"assets":["surv_spring","surv_stone_basin","camp_bottle","river_rock_medium","river_fern","river_moss_rock","mini_clear_river"],"subtitles":[{"en":"Find a clear stream and pour clean water into the bottle.","vi":"Tìm suối trong, lấy nước sạch đổ vào bình.","parts":["Tìm ",["stream","suối",2]," trong, lấy nước ",["clean","sạch",1]," đổ vào ",["bottle","bình",2],"."]},{"en":"Dirty water must not be drunk.","vi":"Nước bẩn thì không được uống.","parts":["Nước ",["dirty","bẩn",1]," thì không được uống."]}]},{"n":3,"title":"Nhiệm vụ 2: Đá nhọn và gậy gỗ","minutes":5,"optional":false,"goal":"Gom 3 gậy và 3 đá nhọn để dựng bẫy dây vấp và hàng rào cành quanh hang trú.","beats":["Bẫy chỉ làm người Săn Tìm vấp ngã ngồi, cười và mất 5 giây.","Đội Săn Tìm nhận Ống nhòm, soi được một bụi cây mỗi lần.","Bác Sáu thả mật thư đầu tiên trên cành thông.","Thùng container xanh gỉ là kho của trại địch: gọi đúng tên công cụ bên trong mới mở được."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Mỗi câu đúng = nhặt được một món; món hiện viền sáng trong cỏ.","reward":"Mở khóa Bẫy dây vấp (đặt được 1 cái/người).","vocab":["stick","stone","sharp","trap","build","container","storage"],"assets":["surv_stick","surv_pointed_stone","surv_tripwire","surv_trap_rope","river_branch","river_rock_small","surv_container_blue"],"subtitles":[{"en":"Gather sticks and sharp stones.","vi":"Gom gậy và đá nhọn.","parts":["Gom ",["stick","gậy",1]," và ",["stone","đá",1]," ",["sharp","nhọn",2],"."]},{"en":"Use them to build a tripwire trap.","vi":"Dùng chúng để dựng bẫy dây.","parts":["Dùng chúng để ",["build","dựng",1]," ",["trap","bẫy",3]," dây."]}]},{"n":4,"title":"Nhiệm vụ 3: Mật thư của bác Kiểm lâm","minutes":5,"optional":false,"goal":"Giải mật thư tiếng Anh để biết lối vào Hang Rêu, nơi an toàn nhất bờ sông.","beats":["Mật thư là một đoạn chỉ đường bị xáo chữ.","Người ở Chuồng Gỗ giải cùng: mỗi câu họ đúng gửi một chữ cho đội.","Đội Săn Tìm đoán được hướng nếu đội Chạy Trốn trả lời sai nhiều."],"question_hook":"Mật thư hiện như tờ giấy cũ; mỗi câu đúng làm hiện một chữ cái bị mờ. Câu dạng sắp xếp từ và điền từ rất hợp ở chặng này.","reward":"Mở đường tắt vào Hang Rêu (ẩn nấp sâu 30 giây).","vocab":["north","left","behind","cave","across"],"assets":["surv_letter","surv_map","surv_compass","river_cave","river_moss_rock","river_cliff"],"subtitles":[{"en":"Solve the secret letter to find the cave entrance.","vi":"Giải mật thư để tìm lối vào hang.","parts":["Giải mật thư để tìm lối vào ",["cave","hang",1],"."]},{"en":"Go north, then turn left.","vi":"Đi bắc, rồi rẽ trái.","parts":["Đi ",["north","bắc",2],", rồi rẽ ",["left","trái",0],"."]}]},{"n":5,"title":"Nhiệm vụ 4: Xóa dấu và thùng lưới bỏ quên","minutes":5,"optional":false,"goal":"Xóa dấu chân trên cát và bùn; lẻn đến thùng Lưới Gắn Thẻ dự phòng ở trại cờ cam.","beats":["Dấu chân mỗi người để lại mờ dần sau 40 giây; chổi cành xóa ngay.","Thùng lưới mở sau 3 câu đúng liên tiếp của cùng một tiểu đội.","Lưới cướp được: đuổi ngược (người Săn Tìm đứng yên 10 giây) hoặc mở Chuồng Gỗ cứu 2 bạn.","Thùng lưới nằm trong thuyền chèo bỏ quên cạnh bờ: tìm ra nó để lấy Lưới Cướp.","Nỏ bắn lưới của Đội Săn Tìm nằm gần thùng lưới bỏ quên: chỉ cướp được khi đọc đúng ba bộ phận."],"question_hook":"Chổi quét dấu: mỗi câu đúng xóa một vệt dấu chân. Nút \"Cướp lưới\" hiện khi lẻn sát sau lưng người Săn Tìm: một câu 8 giây.","reward":"Lưới Gắn Thẻ (3 lần dùng hoặc 60 giây).","vocab":["footprint","sand","mud","sweep","hide","net","rowboat","launcher"],"assets":["surv_broom","decal_footprint_sand","decal_footprint_mud","surv_crate","surv_capture_net","surv_barrel","river_boat_row","surv_net_launcher_a"],"subtitles":[{"en":"Wipe away your footprints on the sand and mud.","vi":"Xóa dấu chân trên cát và bùn.","parts":["Xóa ",["footprint","dấu chân",3]," trên ",["sand","cát",1]," và ",["mud","bùn",2],"."]},{"en":"Hide well so you are not caught.","vi":"Trốn thật kỹ kẻo bị bắt.","parts":[["Hide","Trốn",2]," thật kỹ kẻo bị bắt."]}]},{"n":6,"title":"Trống trại lúc hoàng hôn","minutes":5,"optional":false,"goal":"Phút cuối: giải cứu, đuổi ngược, giữ người. Hết giờ đếm đầu người.","beats":["Mặt trời lặn, đèn pin bật; bụi cây tối hơn nên dễ trốn hơn.","60 giây cuối: mọi Chuồng Gỗ mở thêm một lượt giải cứu nếu đội trả lời đúng 5 câu liền.","Trống vang, màn hình đếm người tự do và người bị bắt, công bố MVP và \"Gương Mặt Quật Cường\"."],"question_hook":"Câu hỏi nhanh 10 giây hiện trên Chuồng Gỗ (giải cứu) và trên đèn pin (Săn Tìm soi khu).","reward":"MVP đội thắng nhận thêm 20% tổng điểm đội thua.","vocab":["free","caught","team","win","brave"],"assets":["surv_holding_pen","surv_flashlight","hdri_sunset","river_birds","anim_cheer","anim_sad"],"subtitles":[{"en":"The drum sounds at sunset: free your teammates!","vi":"Trống vang lúc hoàng hôn: giải cứu đồng đội!","parts":["Trống vang lúc hoàng hôn: ",["free","giải cứu",2]," đồng đội!"]},{"en":"The whole team is so brave, and the team with the most players left wins!","vi":"Cả đội thật dũng cảm, đội còn nhiều người nhất thắng!","parts":["Cả ",["team","đội",1]," thật ",["brave","dũng cảm",2],", đội còn nhiều người nhất ",["win","thắng",1],"!"]}]},{"n":7,"title":"Chặng phụ: Đêm sương trên sông","minutes":5,"optional":true,"goal":"Khi gia sư kéo dài: sương dày, tầm nhìn 10 m; một vòng giải cứu cuối.","beats":["Đội Săn Tìm mất Quét dấu chân, chỉ còn đèn pin.","Người Chạy Trốn bị bắt có thể tự giải cứu bằng 3 câu khó."],"question_hook":"Câu khó hơn một bậc, thưởng gấp đôi sao.","reward":"Sao đôi.","vocab":["fog","quiet","careful"],"assets":["hdri_night","surv_flashlight","water_normal"],"subtitles":[{"en":"The fog is thick, so move quietly and carefully.","vi":"Sương dày, hãy đi thật khẽ và cẩn thận.","parts":[["Fog","Sương",2]," dày, hãy đi thật ",["quiet","khẽ",2]," và ",["careful","cẩn thận",1],"."]}]},{"n":8,"title":"Chặng phụ: Lửa trại tổng kết","minutes":5,"optional":true,"goal":"Ôn lại 10 từ của trận quanh lửa trại; mỗi bạn chọn một từ và đặt câu.","beats":["Bác Sáu khen từng tiểu đội.","Ảnh kỷ niệm cả lớp với nhân vật của mình."],"question_hook":"Câu ôn tập không tính thua, chỉ cộng sao.","reward":"Huy hiệu \"Thoát khỏi Trại Cờ Cam\".","vocab":["camp","fire","friend","remember"],"assets":["camp_firepit","camp_lantern","anim_wave"],"subtitles":[{"en":"Around the campfire, each of you picks a word to remember: fire, friend.","vi":"Quanh lửa trại, mỗi bạn chọn một từ để nhớ: lửa, bạn.","parts":["Quanh lửa ",["camp","trại",0],", mỗi bạn chọn một từ để nhớ: ",["fire","lửa",0],", ",["friend","bạn",1],"."]}]}],{"map_zones":["Bãi sỏi","Rừng thông","Nhà gỗ cỏ cao"]},["anim_cheer","anim_rope_rub","anim_sad","anim_wave","camp_bottle","camp_firepit","camp_lantern","decal_footprint_mud","decal_footprint_sand","hdri_night","hdri_sunset","mini_clear_river","river_birds","river_boat_row","river_branch","river_cave","river_cliff","river_fern","river_moss_rock","river_rock_medium","river_rock_small","surv_barrel","surv_broom","surv_capture_net","surv_compass","surv_container_blue","surv_crate","surv_flag","surv_flashlight","surv_holding_pen","surv_letter","surv_map","surv_net_launcher_a","surv_pen_wall_window","surv_pointed_stone","surv_rival_tent","surv_rope","surv_rope_cut","surv_sharp_rock","surv_spring","surv_stake","surv_stick","surv_stone_basin","surv_trap_rope","surv_tripwire","water_normal"]],["surv-02",2,"Bí mật Thác Ba Tầng","Rừng sông hẻo lánh trong file + ý tưởng hang sau thác; nước trong nhìn thấy đá đáy như video.","Đội Săn Tìm năm nay chọn đúng thác Ba Tầng làm sân đấu và nhốt nhóm bạn trong chuồng gỗ dưới chân thác. Tiếng nước ầm ầm che tiếng mài dây, nên Mai Anh cắt được dây và mở cổng mà không ai nghe thấy. Truyền thuyết của trại kể rằng sau tầng thác giữa có một hang khô, chỉ ai đọc được ba tấm bia khắc chữ tiếng Anh mới tìm ra lối vào. Cả đội phải tìm nước suối trong, gom đá và gậy dựng chốt chặn ở cầu treo, giải bia đá, rồi xóa dấu chân ướt trên đá trơn. Ở tầng cao nhất, Đội Săn Tìm cất kho Lưới Gắn Thẻ trong một thùng gỗ cạnh cầu vồng: ai lấy được sẽ lật ngược trận đấu.","Hẻm núi có thác nước ba tầng, bụi nước mờ như sương, vách đá phủ rêu, cầu gỗ treo bắc qua tầng giữa. Buổi chiều nắng xiên qua bụi nước tạo cầu vồng. Thác nước ba tầng đổ xuống hồ phía dưới; một thác cao một tầng nằm khuất bên phải.",[{"n":1,"title":"Dưới chân thác","minutes":5,"optional":false,"goal":"Mài dây mở chuồng gỗ dưới tiếng thác; Đội Săn Tìm leo lên tầng giữa đặt chốt.","beats":["Tiếng thác làm mờ âm thanh: Đội Săn Tìm không nghe được bước chạy trong 60 giây đầu.","Cổng bung khi đủ số câu đúng của cả nhóm.","Đội nghe tiếng thác dội: gọi đúng tên các tầng thác để định hướng."],"question_hook":"Câu hỏi hiện trên sợi dây ướt; mỗi câu đúng là một nhát mài.","reward":"Mở khóa giày bám đá.","vocab":["waterfall","loud","wet","climb","mist"],"assets":["surv_holding_pen","surv_rope","surv_sharp_rock","river_cliff","river_moss_rock","water_foam","river_waterfall"],"subtitles":[{"en":"The waterfall is loud and the rocks are wet.","vi":"Tiếng thác ầm ầm, mặt đá ướt.","parts":["Tiếng ",["waterfall","thác",2]," ",["loud","ầm ầm",2],", mặt đá ",["wet","ướt",1],"."]},{"en":"Climb slowly through the mist.","vi":"Leo thật chậm giữa làn sương.","parts":[["Climb","Leo",1]," thật chậm giữa làn ",["mist","sương",3],"."]}]},{"n":2,"title":"Nhiệm vụ 1: Giọt nước trong","minutes":5,"optional":false,"goal":"Hứng nước từ khe đá sạch, tránh vũng nước đọng có bọ gậy.","beats":["Ba khe đá, chỉ một khe nước chảy liên tục.","Đội Săn Tìm dùng Quét dấu chân trên đá ướt (dấu ướt hiện rõ hơn).","Giọt nước trong rơi xuống hồ chân thác: múc ở đây."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).","reward":"Bình nước + 1 lần Ẩn nấp sâu.","vocab":["drop","fresh","pond","insect","clear water","pool"],"assets":["surv_spring","surv_stone_basin","camp_bottle","river_rock_large","river_waterfall_pool"],"subtitles":[{"en":"Drink fresh water from the rock crack, not stagnant pond water.","vi":"Uống nước sạch từ khe đá, đừng uống nước ao đọng.","parts":["Uống nước ",["fresh","sạch",2]," từ khe đá, đừng uống nước ",["pond","ao",3]," đọng."]},{"en":"Every drop of water is precious.","vi":"Từng giọt nước đều quý.","parts":["Từng ",["drop","giọt",2]," nước đều quý."]}]},{"n":3,"title":"Nhiệm vụ 2: Chốt chặn cầu treo","minutes":5,"optional":false,"goal":"Gom gậy và đá nhọn dựng hàng rào cành ở đầu cầu treo, làm chậm Đội Săn Tìm.","beats":["Hàng rào làm người Săn Tìm phải đi vòng 8 giây.","Cầu treo lắc khi có hơn 4 người đứng trên.","Thùng container đỏ chặn đường cầu treo: giải câu đố để kéo nó sang bên."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Mỗi câu đúng gắn thêm một cành vào hàng rào.","reward":"Hàng rào cành (1 cái/tiểu đội).","vocab":["bridge","fence","slow","branch","barrier","container"],"assets":["river_bridge","surv_stick","surv_pointed_stone","river_branch","river_fence","surv_container_red"],"subtitles":[{"en":"Build a branch fence at the end of the hanging bridge.","vi":"Dựng hàng rào cành ở đầu cầu treo.","parts":["Dựng ",["fence","hàng rào",3]," cành ở đầu ",["bridge","cầu",1]," treo."]},{"en":"Slow the Seekers down with tree branches.","vi":"Làm chậm Đội Săn Tìm bằng cành cây.","parts":["Làm ",["slow","chậm",1]," Đội Săn Tìm bằng cành ",["branch","cây",2],"."]}]},{"n":4,"title":"Nhiệm vụ 3: Ba tấm bia đá","minutes":5,"optional":false,"goal":"Đọc ba tấm bia để ghép ra lối vào hang sau thác.","beats":["Mỗi bia một câu chỉ đường bị mất chữ.","Người ở chuồng gỗ đọc bia qua ống nhòm và gửi chữ cho đội.","Trinh sát vẫy tay gọi đồng đội đi theo hướng đúng: đọc đúng câu chỉ đường trên bia thì cả nhóm theo kịp."],"question_hook":"Bia đá phủ rêu; mỗi câu đúng làm rêu tan bớt, lộ một chữ. Hợp với câu điền từ (cloze).","reward":"Lối vào hang sau thác.","vocab":["stone","behind","through","secret","come here","this way"],"assets":["surv_letter","river_cave","river_cliff","river_moss_rock","anim_beckon"],"subtitles":[{"en":"Read the three stone tablets to piece together the path.","vi":"Đọc ba tấm bia đá để ghép ra lối đi.","parts":["Đọc ba tấm bia ",["stone","đá",1]," để ghép ra lối đi."]},{"en":"The entrance is behind the waterfall; go through the curtain of water.","vi":"Lối vào ở phía sau thác, đi xuyên qua màn nước.","parts":["Lối vào ở ",["behind","phía sau",3]," thác, đi ",["through","xuyên qua",3]," màn nước."]}]},{"n":5,"title":"Nhiệm vụ 4: Dấu chân ướt và thùng lưới cầu vồng","minutes":5,"optional":false,"goal":"Xóa dấu chân ướt trên đá; lẻn lên tầng cao lấy Lưới Gắn Thẻ.","beats":["Dấu chân ướt khô dần sau 30 giây dưới nắng.","Thùng lưới cạnh cầu vồng, được Kenzo canh giữ."],"question_hook":"Chổi cành xóa dấu theo câu đúng; nút \"Cướp lưới\" khi lẻn sau lưng người Săn Tìm.","reward":"Lưới Gắn Thẻ.","vocab":["rainbow","dry","sneak","top"],"assets":["surv_broom","decal_footprint_mud","surv_crate","surv_capture_net"],"subtitles":[{"en":"A rainbow appears, and the wet rocks need drying.","vi":"Cầu vồng hiện lên, đá ướt cần lau khô.","parts":[["Rainbow","Cầu vồng",2]," hiện lên, đá ướt cần lau ",["dry","khô",1],"."]},{"en":"Wipe the wet footprints and sneak to the top.","vi":"Xóa dấu chân ướt, rón rén lên tầng cao.","parts":["Xóa dấu chân ướt, ",["sneak","rón rén",3]," lên ",["top","tầng cao",1],"."]}]},{"n":6,"title":"Cầu vồng tắt","minutes":5,"optional":false,"goal":"Nắng tắt, cầu vồng biến mất: phút cuối giải cứu và đếm người.","beats":["Bụi nước dày lên, che bớt tầm nhìn.","Công bố kết quả, MVP và Gương Mặt Quật Cường."],"question_hook":"Câu 10 giây trên chuồng gỗ và trên ống nhòm.","reward":"MVP +20% điểm đội thua.","vocab":["last","rescue","count","winner"],"assets":["surv_holding_pen","surv_binoculars","hdri_sunset","anim_cheer"],"subtitles":[{"en":"The rainbow fades: the last minute to rescue.","vi":"Cầu vồng tắt: phút cuối giải cứu.","parts":["Cầu vồng tắt: phút ",["last","cuối",1]," ",["rescue","giải cứu",3],"."]},{"en":"Count the whole team: whoever is complete is the winner.","vi":"Đếm cả đội, ai về đủ là người thắng.","parts":[["Count","Đếm",1]," cả đội, ai về đủ là ",["winner","người thắng",2],"."]}]},{"n":7,"title":"Chặng phụ: Hang sau thác","minutes":5,"optional":true,"goal":"Kéo dài: cả hai đội vào hang tối, chỉ có đèn pin.","beats":["Ai đứng yên trong bóng tối 5 giây thì Ống nhòm không thấy."],"question_hook":"Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["dark","echo","torch"],"assets":["river_cave","surv_flashlight"],"subtitles":[{"en":"In the dark cave, there is only a torch.","vi":"Trong hang tối, chỉ có chiếc đèn pin.","parts":["Trong hang ",["dark","tối",1],", chỉ có chiếc ",["torch","đèn pin",2],"."]}]},{"n":8,"title":"Chặng phụ: Kể chuyện bên thác","minutes":5,"optional":true,"goal":"Mỗi tiểu đội kể lại đường thoát của mình bằng 3 câu tiếng Anh.","beats":["Bình chọn câu chuyện hay nhất."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng bên lửa trại. Câu sắp xếp câu kể, không tính thua.","reward":"Huy hiệu \"Người giữ bí mật Thác Ba Tầng\".","vocab":["story","first","then","finally"],"assets":["camp_firepit","anim_wave"],"subtitles":[{"en":"First I climbed up; then I ran; finally I escaped.","vi":"Đầu tiên, em trèo lên; sau đó em chạy; cuối cùng em thoát.","parts":[["First","Đầu tiên",1],", em trèo lên; ",["then","sau đó",1]," em chạy; ",["finally","cuối cùng",3]," em thoát."]}]}],{"map_zones":["Chân thác","Cầu treo tầng giữa","Đỉnh thác cầu vồng"]},["anim_beckon","anim_cheer","anim_wave","camp_bottle","camp_firepit","decal_footprint_mud","hdri_sunset","river_branch","river_bridge","river_cave","river_cliff","river_fence","river_moss_rock","river_rock_large","river_waterfall","river_waterfall_pool","surv_binoculars","surv_broom","surv_capture_net","surv_container_red","surv_crate","surv_flashlight","surv_holding_pen","surv_letter","surv_pointed_stone","surv_rope","surv_sharp_rock","surv_spring","surv_stick","surv_stone_basin","water_foam"]],["surv-03",3,"Đêm Đom Đóm Rừng Thông","Video rừng thông và lều phát sáng ban đêm; file: lẩn trốn bụi cây, đội truy đuổi dùng bản đồ quét.","Đêm cuối trại, bác Ba bảo vệ tổ chức trận \"Đom Đóm\": Đội Săn Tìm cầm đèn pin, Đội Chạy Trốn chỉ có ánh sáng đom đóm. Mở màn, cả nhóm bị dồn vào chuồng gỗ ở bãi đèn lồng; Gia Bảo mài dây trên một hòn đá sắc dưới ánh trăng và cả nhóm thoát vào rừng. Đom đóm bay theo người trả lời đúng, vừa soi đường vừa dễ làm lộ chỗ trốn, nên mỗi bước phải tính toán. Muốn sống sót đến khi tiếng chuông 12 giờ vang, đội phải lấy nước ở suối trăng, làm bẫy dây, giải mật thư viết bằng mực phát sáng và xóa dấu chân trên lá kim. Đội Săn Tìm cất Lưới Gắn Thẻ dự phòng trong túi treo trên cây thông cổ thụ: ai leo tới được sẽ đổi vai, đuổi ngược đội cầm đèn.","Rừng thông ven sông vào ban đêm, trăng lưỡi liềm, hàng nghìn đom đóm bay trên bãi cỏ. Đèn lồng giấy treo dọc lối mòn; mặt sông lấp lánh ánh trăng.",[{"n":1,"title":"Bãi đèn lồng","minutes":5,"optional":false,"goal":"Thoát chuồng gỗ dưới trăng; Đội Săn Tìm bật đèn pin, chia khu rừng.","beats":["Đèn lồng giấy đung đưa, bóng cây đổ dài.","Mỗi câu đúng: một nhát mài dây; đom đóm bay quanh người đúng.","Cậu bé leo tháp canh quan sát bãi đèn lồng: gọi đúng vị trí đèn để báo cho đội."],"question_hook":"Câu hỏi hiện trên sợi dây dưới ánh trăng.","reward":"Mở khóa Đom đóm dẫn đường.","vocab":["night","moon","lantern","firefly","lookout"],"assets":["surv_holding_pen","surv_rope","surv_sharp_rock","camp_lantern","camp_string_lights","hdri_night","watchtower","char_gamer_boy"],"subtitles":[{"en":"Under the moon, everyone escapes the wooden pen.","vi":"Dưới trăng, mọi người thoát chuồng gỗ.","parts":["Dưới ",["moon","trăng",0],", mọi người thoát chuồng gỗ."]},{"en":"Fireflies glow like tiny lanterns.","vi":"Đom đóm sáng như những chiếc đèn lồng nhỏ.","parts":[["Firefly","Đom đóm",3]," sáng như những chiếc ",["lantern","đèn lồng",2]," nhỏ."]}]},{"n":2,"title":"Nhiệm vụ 1: Suối trăng","minutes":5,"optional":false,"goal":"Tìm khúc suối có trăng soi đáy (nước trong), lấy nước trước khi đèn pin quét tới.","beats":["Nước đục không phản chiếu trăng.","Đội Săn Tìm: mỗi câu đúng làm đèn pin sáng xa thêm 3 m."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).","reward":"Bình nước.","vocab":["reflect","clear","shine","bright"],"assets":["surv_spring","camp_bottle","water_normal","river_reed"],"subtitles":[{"en":"The stream reflects the moon and the clear water shows its bottom.","vi":"Suối phản chiếu trăng, nước trong thấy đáy.","parts":["Suối ",["reflect","phản chiếu",3]," trăng, nước ",["clear","trong",2]," thấy đáy."]},{"en":"The moonlight makes the stream shine.","vi":"Ánh trăng làm dòng suối thêm lấp lánh.","parts":["Ánh trăng làm dòng suối thêm ",["shine","lấp lánh",2],"."]}]},{"n":3,"title":"Nhiệm vụ 2: Bẫy dây trong bóng tối","minutes":5,"optional":false,"goal":"Gom gậy và đá dựng bẫy dây vấp quanh lối mòn.","beats":["Bẫy chạm vào thì kêu lục lạc và làm người Săn Tìm ngồi bệt 5 giây.","Đom đóm né khu có bẫy, nên phải nhớ vị trí.","Lính gác máy của trại địch quét bãi bẫy: nhìn vào tia sáng để biết lúc nào an toàn đi qua."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).","reward":"Bẫy dây lục lạc.","vocab":["bell","path","step","careful","sentinel","tripwire"],"assets":["surv_stick","surv_pointed_stone","surv_tripwire","river_branch","river_tree_pine","surv_sentinel"],"subtitles":[{"en":"Gather sticks and stones for a tripwire around the path.","vi":"Gom gậy và đá dựng bẫy dây quanh lối mòn.","parts":["Gom gậy và đá dựng ",["tripwire","bẫy dây",4]," quanh ",["path","lối mòn",2],"."]},{"en":"A small bell on the wire rings when someone steps over it.","vi":"Chuông nhỏ treo trên dây sẽ kêu khi ai bước qua.","parts":[["Bell","Chuông",2]," nhỏ treo trên dây sẽ kêu khi ai ",["step","bước",1]," qua."]}]},{"n":4,"title":"Nhiệm vụ 3: Mật thư mực phát sáng","minutes":5,"optional":false,"goal":"Đọc mật thư chỉ hiện chữ khi có đom đóm bay qua.","beats":["Mỗi câu đúng gọi một đàn đom đóm tới làm sáng một dòng.","Người ở chuồng gỗ đọc tiếp những dòng còn mờ."],"question_hook":"Mật thư mực phát sáng: câu đúng làm từng chữ sáng lên; hợp câu sắp xếp và điền từ.","reward":"Vị trí cây thông cổ thụ.","vocab":["glow","old","tree","tall"],"assets":["surv_letter","surv_compass","river_tree_pine","river_butterfly"],"subtitles":[{"en":"The secret letter only glows when a firefly flies past.","vi":"Mật thư chỉ sáng lên khi đom đóm bay qua.","parts":["Mật thư chỉ ",["glow","sáng lên",2]," khi đom đóm bay qua."]},{"en":"Go to the oldest and tallest tree.","vi":"Đi tới cái cây cổ và cao nhất.","parts":["Đi tới cái cây ",["old","cổ",1]," và ",["tall","cao",1]," nhất."]}]},{"n":5,"title":"Nhiệm vụ 4: Lá kim và túi lưới trên cây","minutes":5,"optional":false,"goal":"Xóa dấu chân trên lá kim; leo cây thông cổ thụ lấy Lưới Gắn Thẻ.","beats":["Dấu trên lá kim mờ nhanh nhưng phát tiếng sột soạt.","Leo cây cần 3 câu đúng liên tiếp."],"question_hook":"Chổi lá thông xóa dấu theo câu đúng; nút \"Cướp lưới\" sau lưng người Săn Tìm.","reward":"Lưới Gắn Thẻ.","vocab":["leaf","needle","climb","quiet"],"assets":["surv_broom","decal_footprint_mud","surv_capture_net","river_tree_pine"],"subtitles":[{"en":"Pine needles on the ground hide your footprints.","vi":"Lá kim rải dưới đất che dấu chân.","parts":[["Leaf","Lá",1]," ",["needle","kim",3]," rải dưới đất che dấu chân."]},{"en":"Climb the pine tree very quietly.","vi":"Leo cây thông thật khẽ.","parts":[["Climb","Leo",1]," cây thông thật ",["quiet","khẽ",2],"."]}]},{"n":6,"title":"Chuông 12 giờ","minutes":5,"optional":false,"goal":"Phút cuối đếm người dưới tiếng chuông.","beats":["Đom đóm tụ lại thành chữ tên đội thắng trên bầu trời.","MVP và Gương Mặt Quật Cường."],"question_hook":"Câu 10 giây trên chuồng gỗ và đèn pin.","reward":"MVP +20% điểm đội thua.","vocab":["midnight","bell","stars"],"assets":["surv_holding_pen","surv_flashlight","hdri_night","anim_cheer"],"subtitles":[{"en":"Midnight: the bell rings.","vi":"Nửa đêm: tiếng chuông vang lên.","parts":[["Midnight","Nửa đêm",3],": tiếng ",["bell","chuông",2]," vang lên."]},{"en":"Count the people under the stars.","vi":"Đếm người dưới ánh sao.","parts":["Đếm người dưới ánh ",["stars","sao",1],"."]}]},{"n":7,"title":"Chặng phụ: Mưa sao băng","minutes":5,"optional":true,"goal":"Kéo dài: mưa sao băng làm sáng rừng 5 phút, cả hai đội cùng lộ.","beats":["Mỗi sao băng = một câu thưởng."],"question_hook":"Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["wish","sky","shooting star"],"assets":["hdri_night"],"subtitles":[{"en":"Each shooting star is a wish in the sky.","vi":"Mỗi sao băng là một điều ước dưới bầu trời.","parts":["Mỗi ",["shooting star","sao băng",3]," là một điều ước dưới ",["sky","bầu trời",1],"."]}]},{"n":8,"title":"Chặng phụ: Lời chúc dưới trăng","minutes":5,"optional":true,"goal":"Viết lời chúc tiếng Anh cho bạn cùng đội.","beats":["Lời chúc hiện trên đèn lồng thả trôi sông."],"question_hook":"Câu viết ngắn chấm theo tiêu chí, không tính thua.","reward":"Huy hiệu \"Đom Đóm Dũng Cảm\".","vocab":["hope","wish","kind"],"assets":["camp_lantern","water_normal"],"subtitles":[{"en":"I hope you are always kind.","vi":"Tôi mong bạn luôn tử tế.","parts":["Tôi ",["hope","mong",2]," bạn luôn ",["kind","tử tế",2],"."]}]}],{"map_zones":["Bãi đèn lồng","Suối trăng","Cây thông cổ thụ"]},["anim_cheer","camp_bottle","camp_lantern","camp_string_lights","char_gamer_boy","decal_footprint_mud","hdri_night","river_branch","river_butterfly","river_reed","river_tree_pine","surv_broom","surv_capture_net","surv_compass","surv_flashlight","surv_holding_pen","surv_letter","surv_pointed_stone","surv_rope","surv_sentinel","surv_sharp_rock","surv_spring","surv_stick","surv_tripwire","watchtower","water_normal"]],["surv-04",4,"Cơn Mưa Trên Sông Đá","File: xóa dấu chân trên cát/bùn để đánh lạc hướng; video bờ đá sỏi và rừng ẩm.","Giữa buổi chiều, mây đen kéo về, Đội Săn Tìm tranh thủ nhốt nhóm bạn vào chuồng gỗ dưới mái lá chuối. Khi tia chớp đầu tiên lóe lên, Thiên Ân mài đứt dây thừng trên tảng đá sắc và cả nhóm lao vào màn mưa. Mưa là bạn và cũng là thù: mưa xóa dấu chân trên cát nhưng lại in dấu thật sâu trên bùn. Đội phải hứng nước mưa sạch, dựng mái che bằng gậy và lá chuối, giải mật thư bị nhòe nước, và dụ Đội Săn Tìm theo dấu chân giả. Khi sấm nổ lớn, Đội Săn Tìm phải chạy về trại cất lưới, đó là lúc đội Chạy Trốn cướp được lưới để giải cứu bạn bè.","Bờ sông đá cuội đầu mùa mưa, mây đen kéo từ thượng nguồn, mưa rào từng đợt. Bùn non dọc bờ, lá chuối rừng to như cái ô, sấm rền xa.",[{"n":1,"title":"Tia chớp đầu tiên","minutes":5,"optional":false,"goal":"Thoát chuồng gỗ khi mưa bắt đầu; Đội Săn Tìm nhận áo mưa cam.","beats":["Mỗi tia chớp làm sáng cả bãi 1 giây: ai đang chạy có thể bị thấy.","Đủ câu đúng thì dây đứt."],"question_hook":"Câu hỏi hiện trên sợi dây ướt mưa.","reward":"Mở khóa Lá chuối (che mưa, giảm dấu chân).","vocab":["rain","lightning","thunder","wet"],"assets":["surv_holding_pen","surv_rope","surv_sharp_rock","hdri_cloudy","river_bush"],"subtitles":[{"en":"Lightning flashes, thunder rolls, and the rain pours!","vi":"Tia chớp sáng và sấm vang: mưa đổ!","parts":["Tia ",["lightning","chớp",2]," sáng và ",["thunder","sấm",3]," vang: ",["rain","mưa",0]," đổ!"]},{"en":"The orange raincoats are soaking wet, but everyone smiles.","vi":"Áo mưa cam ướt sũng nhưng ai cũng cười.","parts":["Áo mưa cam ",["wet","ướt",1]," sũng nhưng ai cũng cười."]}]},{"n":2,"title":"Nhiệm vụ 1: Hứng nước mưa","minutes":5,"optional":false,"goal":"Đặt ống tre và chậu đá hứng nước mưa sạch; tránh nước bùn chảy tràn.","beats":["Chậu đặt dưới mái lá thì sạch, đặt trên đất thì đục.","Đội Săn Tìm quét dấu trên bùn rõ gấp đôi."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).","reward":"Bình nước mưa.","vocab":["collect","bowl","roof","muddy"],"assets":["surv_stone_basin","camp_bucket","camp_bottle","tex_mud"],"subtitles":[{"en":"Collect rainwater in a clean stone bowl.","vi":"Hứng nước mưa vào chậu đá sạch.","parts":[["Collect","Hứng",2]," nước mưa vào ",["bowl","chậu",2]," đá sạch."]},{"en":"Do not take the muddy runoff water.","vi":"Đừng lấy nước bùn chảy tràn.","parts":["Đừng lấy nước ",["muddy","bùn",2]," chảy tràn."]}]},{"n":3,"title":"Nhiệm vụ 2: Mái che gậy và lá","minutes":5,"optional":false,"goal":"Gom gậy, đá nhọn và lá chuối dựng mái che, nơi Ống nhòm không soi được.","beats":["Mái che chứa tối đa 4 người.","Bẫy dây vấp đặt quanh mái che."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Câu đúng dựng thêm một cây cột.","reward":"Mái che lá (ẩn nấp sâu).","vocab":["shelter","cover","leaf","dry"],"assets":["surv_stick","surv_pointed_stone","surv_tripwire","camp_tarp","river_bush"],"subtitles":[{"en":"Build a shelter from sticks and banana leaves.","vi":"Dựng mái che từ gậy và lá chuối.","parts":["Dựng ",["shelter","mái che",3]," từ gậy và ",["leaf","lá",1]," chuối."]},{"en":"The roof must cover everything to stay dry.","vi":"Mái phải che kín để giữ khô.","parts":["Mái phải ",["cover","che",2]," kín để giữ ",["dry","khô",1],"."]}]},{"n":4,"title":"Nhiệm vụ 3: Mật thư nhòe nước","minutes":5,"optional":false,"goal":"Khôi phục mật thư bị mưa làm nhòe để tìm hang đá khô.","beats":["Chữ nhòe ghép lại bằng các câu đúng.","Người ở chuồng gỗ giúp bằng câu ngữ pháp.","Mật thư nhòe nước nằm trong trực thăng rơi: đọc câu hỏi trên bảng điều khiển để lấy nó."],"question_hook":"Tờ mật thư nhòe; câu đúng làm khô từng dòng. Hợp câu sửa câu (transform).","reward":"Lối vào hang đá khô.","vocab":["message","smudge","dry cave","under","wreck","letter"],"assets":["surv_letter","river_cave","surv_map","surv_helicopter_wreck"],"subtitles":[{"en":"The rain smudges the secret message.","vi":"Mưa làm mật thư bị nhòe.","parts":["Mưa làm ",["message","mật thư",2]," bị ",["smudge","nhòe",4],"."]},{"en":"Find the dry cave: it lies under a big rock.","vi":"Tìm hang khô: nó nằm dưới tảng đá lớn.","parts":["Tìm ",["dry cave","hang khô",3],": nó nằm ",["under","dưới",1]," tảng đá lớn."]}]},{"n":5,"title":"Nhiệm vụ 4: Dấu chân giả","minutes":5,"optional":false,"goal":"Xóa dấu thật trên bùn và in dấu giả dẫn Đội Săn Tìm ra bãi lau.","beats":["Mỗi câu đúng tạo 5 bước dấu giả.","Sấm lớn: người Săn Tìm phải về trại cất lưới 20 giây, cơ hội cướp lưới.","Mảnh đất bùn ướt in rõ dấu chân: đội nào xóa dấu đúng chỗ thì đội kia lạc hướng."],"question_hook":"Chổi xóa dấu và Mồi nhử theo câu đúng; nút \"Cướp lưới\".","reward":"Lưới Gắn Thẻ.","vocab":["fake","trick","follow","reed","mud","footprint"],"assets":["surv_broom","decal_footprint_mud","decal_footprint_sand","surv_capture_net","river_reed","ground_soil_patch"],"subtitles":[{"en":"Print fake footprints in the mud to trick the seekers.","vi":"In dấu chân giả trên bùn để đánh lừa đội săn.","parts":["In dấu chân ",["fake","giả",3]," trên bùn để ",["trick","đánh lừa",3]," đội săn."]},{"en":"They will follow them to the reed bed.","vi":"Họ sẽ đi theo đến bãi lau.","parts":["Họ sẽ ",["follow","đi theo",1]," đến bãi ",["reed","lau",2],"."]}]},{"n":6,"title":"Tạnh mưa","minutes":5,"optional":false,"goal":"Mưa tạnh, cầu vồng lên: phút cuối giải cứu và đếm người.","beats":["Bùn khô dần, dấu chân mờ đi.","Kết quả, MVP, Gương Mặt Quật Cường."],"question_hook":"Câu 10 giây trên chuồng gỗ.","reward":"MVP +20% điểm đội thua.","vocab":["stop","sun","rainbow","safe"],"assets":["surv_holding_pen","hdri_noon","anim_cheer"],"subtitles":[{"en":"The rain stops, the sun comes out, and a rainbow appears.","vi":"Mưa tạnh, mặt trời ló ra và cầu vồng hiện.","parts":["Mưa ",["stop","tạnh",1],", ",["sun","mặt trời",0]," ló ra và ",["rainbow","cầu vồng",2]," hiện."]},{"en":"The whole team is safe and happy.","vi":"Cả đội an toàn và vui vẻ.","parts":["Cả đội ",["safe","an toàn",1]," và vui vẻ."]}]},{"n":7,"title":"Chặng phụ: Lũ nhỏ","minutes":5,"optional":true,"goal":"Kéo dài: nước sông dâng, bãi thu hẹp, hai đội dồn vào giữa.","beats":["Ai đứng ở bãi thấp phải trả lời để leo lên đá cao."],"question_hook":"Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["flood","rise","high","quick"],"assets":["river_rock_large","water_foam"],"subtitles":[{"en":"A small flood is coming and the water rises high!","vi":"Cơn lũ nhỏ đang tới, nước dâng cao!","parts":["Cơn ",["flood","lũ",3]," nhỏ đang tới, nước ",["rise","dâng",2]," ",["high","cao",1],"!"]}]},{"n":8,"title":"Chặng phụ: Phơi đồ quanh lửa","minutes":5,"optional":true,"goal":"Ôn từ vựng thời tiết quanh đống lửa sưởi.","beats":["Mỗi bạn chọn một từ thời tiết và đặt câu."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng bên lửa trại. Câu ôn, không tính thua.","reward":"Huy hiệu \"Chiến Binh Mưa\".","vocab":["weather","storm","cloud","warm"],"assets":["camp_firepit","river_woodpile"],"subtitles":[{"en":"Review the weather: storm, cloud and warm sun.","vi":"Ôn thời tiết: bão, mây và nắng ấm.","parts":["Ôn ",["weather","thời tiết",2],": ",["storm","bão",2],", ",["cloud","mây",1]," và nắng ",["warm","ấm",1],"."]}]}],{"map_zones":["Bãi đá cuội","Rừng chuối","Bãi lau sậy"]},["anim_cheer","camp_bottle","camp_bucket","camp_firepit","camp_tarp","decal_footprint_mud","decal_footprint_sand","ground_soil_patch","hdri_cloudy","hdri_noon","river_bush","river_cave","river_reed","river_rock_large","river_woodpile","surv_broom","surv_capture_net","surv_helicopter_wreck","surv_holding_pen","surv_letter","surv_map","surv_pointed_stone","surv_rope","surv_sharp_rock","surv_stick","surv_stone_basin","surv_tripwire","tex_mud","water_foam"]],["surv-05",5,"Đảo Lau Sậy Giữa Dòng","File: khu rừng sông dã ngoại hẻo lánh; video thuyền nhôm và mặt nước ngọc.","Đội Săn Tìm đưa nhóm bạn ra cù lao bằng thuyền nhôm, nhốt vào chuồng gỗ cạnh bến rồi chèo đi giấu bè. Quỳnh Như tìm được mảnh đá sắc trong bãi sỏi, mài đứt dây và dẫn cả nhóm vào rừng lau cao quá đầu. Đảo không có suối, nên phải tìm giếng đá cổ của người đánh cá; phải gom gậy làm bè nhỏ, giải mật thư của ông lái đò Tư để biết bến nào an toàn, và xóa vệt đi trong lau. Đội Săn Tìm đi tuần bằng thuyền quanh đảo, dùng ống nhòm từ mặt nước. Lưới Gắn Thẻ dự phòng nằm trên chiếc thuyền neo ở bến cũ; ai bơi bè tới được sẽ đổi vai và giải cứu cả đội.","Một cù lao lau sậy giữa sông rộng, nối với bờ bằng bè tre và bến gỗ cũ. Nắng chiều gay gắt rồi dịu dần, sóng vỗ vào thuyền nhôm, chim cò bay ngang. Cù lao nhìn từ xa có cọ và gốc cây cổ, thuyền chèo neo cạnh bến.",[{"n":1,"title":"Bến cũ cù lao","minutes":5,"optional":false,"goal":"Thoát chuồng gỗ ở bến; Đội Săn Tìm lên thuyền đi tuần.","beats":["Tiếng sóng vỗ, thuyền nhôm rời bến.","Đủ câu đúng thì dây đứt.","Cù lao lau sậy nhìn từ bến cũ: nhận mặt các điểm nhiệm vụ.","Cô lái đò giải thích luật cù lao cho cả hai đội trước khi cho lên bến."],"question_hook":"Câu hỏi trên sợi dây buộc cổng chuồng.","reward":"Mở khóa đường vào rừng lau.","vocab":["island","boat","reed","shore","dock","ferry","guide"],"assets":["surv_holding_pen","surv_rope","surv_sharp_rock","river_dock","river_boat_aluminium","river_reed","mini_large_island","char_generic_female_2"],"subtitles":[{"en":"The old dock on the island, with reeds taller than your head.","vi":"Bến cũ trên cù lao, lau sậy cao quá đầu.","parts":["Bến cũ trên ",["island","cù lao",2],", lau ",["reed","sậy",2]," cao quá đầu."]},{"en":"The Seekers board the boat to patrol.","vi":"Đội Săn Tìm lên thuyền đi tuần.","parts":["Đội Săn Tìm lên ",["boat","thuyền",0]," đi tuần."]}]},{"n":2,"title":"Nhiệm vụ 1: Giếng đá người đánh cá","minutes":5,"optional":false,"goal":"Tìm giếng đá cổ có nước ngọt; nước sông mặn phù sa không uống được.","beats":["Ba giếng, một giếng cạn, một giếng có rêu, một giếng nước trong.","Thuyền tuần soi ống nhòm vào bờ.","Tường đá và gỗ quanh giếng làm Chuồng Gỗ của cù lao: tìm chỗ hở để giải cứu."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).","reward":"Bình nước ngọt.","vocab":["well","fresh water","deep","bucket","stone wall","pen"],"assets":["surv_stone_basin","camp_bucket","river_rock_medium","surv_pen_wall_stone"],"subtitles":[{"en":"The old stone well holds fresh water deep down.","vi":"Giếng đá cổ có nước ngọt dưới đáy sâu.","parts":["Giếng đá cổ có ",["fresh water","nước ngọt",3]," dưới đáy ",["deep","sâu",1],"."]},{"en":"Use a bucket to pull the water up.","vi":"Dùng xô kéo nước lên.","parts":["Dùng ",["bucket","xô",3]," kéo nước lên."]}]},{"n":3,"title":"Nhiệm vụ 2: Bè gậy","minutes":5,"optional":false,"goal":"Gom gậy và dây làm bè nhỏ để qua lạch nước.","beats":["Bè chở 2 người, đi chậm.","Bẫy dây vấp đặt ở bờ lạch."],"question_hook":"Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao). Mỗi câu đúng buộc thêm một thanh gậy vào bè.","reward":"Bè gậy.","vocab":["raft","tie","float","paddle"],"assets":["surv_stick","surv_rope","surv_tripwire","river_driftwood","river_boat_row"],"subtitles":[{"en":"Make a small raft and tie the sticks with rope.","vi":"Làm bè nhỏ, buộc gậy bằng dây.","parts":["Làm ",["raft","bè",3]," nhỏ, ",["tie","buộc",1]," gậy bằng dây."]},{"en":"Only if the raft floats can you paddle across the channel.","vi":"Bè nổi được thì mới chèo qua lạch.","parts":["Bè ",["float","nổi",2]," được thì mới ",["paddle","chèo",1]," qua lạch."]}]},{"n":4,"title":"Nhiệm vụ 3: Mật thư ông lái đò","minutes":5,"optional":false,"goal":"Giải mật thư trong chai trôi dạt để biết bến nào an toàn.","beats":["Chai trôi dạt vào bãi; mật thư ghi giờ thủy triều và hướng bến.","Người ở chuồng gỗ đọc tiếp."],"question_hook":"Mật thư trong chai; câu đúng gỡ từng dòng. Hợp câu đọc hiểu ngắn.","reward":"Bến an toàn.","vocab":["bottle","tide","east","safe"],"assets":["surv_letter","surv_map","surv_compass","camp_bottle"],"subtitles":[{"en":"A drifting bottle holds a secret message.","vi":"Một chai trôi dạt chứa mật thư.","parts":["Một ",["bottle","chai",1]," trôi dạt chứa mật thư."]},{"en":"Read it carefully to know which dock is safe, in the east.","vi":"Đọc kỹ để biết bến nào an toàn, phía đông.","parts":["Đọc kỹ để biết bến nào ",["safe","an toàn",1],", phía ",["east","đông",2],"."]}]},{"n":5,"title":"Nhiệm vụ 4: Vệt lau và thuyền neo","minutes":5,"optional":false,"goal":"Dựng lại lau bị rẽ để xóa vệt; chèo bè tới thuyền neo lấy Lưới Gắn Thẻ.","beats":["Vệt lau rẽ hiện rõ từ thuyền tuần.","Lấy lưới trên thuyền cần 3 câu đúng liên tiếp.","Thuyền chèo neo cạnh bờ chứa thùng lưới; chỉ cướp được khi đọc đúng tên các món trên thuyền.","Nỏ lưới kiểu hoạt hình đặt cạnh thuyền neo: cướp được khi đọc đúng tên ba bộ phận."],"question_hook":"Mỗi câu đúng dựng lại một khóm lau; nút \"Cướp lưới\".","reward":"Lưới Gắn Thẻ.","vocab":["hide","trail","anchor","swim","rowboat","launcher","net"],"assets":["river_reed","surv_capture_net","river_boat_aluminium","decal_footprint_sand","river_boat_row","surv_net_launcher_b"],"subtitles":[{"en":"Stand the reeds back up to hide your trail.","vi":"Dựng lau lên để giấu vệt đi.","parts":["Dựng lau lên để ",["hide","giấu",2]," ",["trail","vệt",3]," đi."]},{"en":"Paddle the raft to the anchored boat to get the net.","vi":"Chèo bè tới chiếc thuyền neo lấy lưới.","parts":["Chèo bè tới chiếc thuyền ",["anchor","neo",3]," lấy lưới."]}]},{"n":6,"title":"Hoàng hôn trên cù lao","minutes":5,"optional":false,"goal":"Phút cuối giải cứu, đếm người khi mặt trời chạm sông.","beats":["Chim cò bay về tổ.","MVP và Gương Mặt Quật Cường.","Phao cứu sinh treo ở bến là mốc để đội đếm người cuối trận."],"question_hook":"Câu 10 giây trên chuồng gỗ và trên thuyền tuần.","reward":"MVP +20% điểm đội thua.","vocab":["sunset","island","together","lifebuoy"],"assets":["surv_holding_pen","hdri_sunset","river_birds","anim_cheer","river_buoy"],"subtitles":[{"en":"Sunset over the island, and the whole team counts together.","vi":"Hoàng hôn trên cù lao, cả đội cùng nhau đếm người.","parts":[["Sunset","Hoàng hôn",2]," trên ",["island","cù lao",2],", cả đội ",["together","cùng nhau",1]," đếm người."]},{"en":"A lifebuoy rests by the dock.","vi":"Chiếc phao cứu hộ nằm bên bến.","parts":["Chiếc ",["lifebuoy","phao cứu hộ",3]," nằm bên bến."]}]},{"n":7,"title":"Chặng phụ: Nước ròng","minutes":5,"optional":true,"goal":"Kéo dài: nước rút lộ bãi cát mới, đường trốn thay đổi.","beats":["Bãi cát mới in dấu chân rất rõ."],"question_hook":"Câu hỏi hiện trên Bảng Nhiệm vụ và trên Chuồng Gỗ như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["low tide","sandbar"],"assets":["tex_sand","decal_footprint_sand"],"subtitles":[{"en":"Low tide reveals a new sandbar.","vi":"Nước ròng lộ ra bãi cát mới.","parts":[["Low tide","Nước ròng",3]," lộ ra ",["sandbar","bãi cát",4]," mới."]}]},{"n":8,"title":"Chặng phụ: Chuyến đò về","minutes":5,"optional":true,"goal":"Cả lớp lên đò về bờ, ông Tư hỏi bài.","beats":["Ai trả lời đúng được cầm lái đò một đoạn."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng bên lửa trại. Câu ôn, không tính thua.","reward":"Huy hiệu \"Thủ Lĩnh Cù Lao\".","vocab":["ferry","home","thank you"],"assets":["river_boat_row","river_dock"],"subtitles":[{"en":"The ferry takes the class home; say thank you to Mr. Tu.","vi":"Đò đưa cả lớp về nhà; em nói cảm ơn ông Tư.","parts":["Đò đưa cả lớp về ",["home","nhà",0],"; em nói ",["thank you","cảm ơn",0]," ông Tư."]}]}],{"map_zones":["Bến cũ","Rừng lau","Bãi giếng đá"],"note":"Đội Săn Tìm đi tuần bằng 2 thuyền (tối đa 6 người/thuyền); số còn lại tuần trên bờ."},["anim_cheer","camp_bottle","camp_bucket","char_generic_female_2","decal_footprint_sand","hdri_sunset","mini_large_island","river_birds","river_boat_aluminium","river_boat_row","river_buoy","river_dock","river_driftwood","river_reed","river_rock_medium","surv_capture_net","surv_compass","surv_holding_pen","surv_letter","surv_map","surv_net_launcher_b","surv_pen_wall_stone","surv_rope","surv_sharp_rock","surv_stick","surv_stone_basin","surv_tripwire","tex_sand"]]]$j$::jsonb) e
on conflict (id) do update set game = excluded.game, seq = excluded.seq, title = excluded.title, inspiration = excluded.inspiration,
  story = excluded.story, setting = excluded.setting, stages = excluded.stages, class_plan = excluded.class_plan,
  asset_ids = excluded.asset_ids, rounds = excluded.rounds, minutes_per_round = excluded.minutes_per_round, character_count = excluded.character_count, active = true, plan_version = 2;
